func warnStaleEndedSessionsTo(ctx context.Context, count int, w io.Writer) {
	commonDir, err := GetGitCommonDir(ctx)
	if err != nil {
		return // fail-open
	}
	warnDir := filepath.Join(commonDir, session.SessionStateDirName)
	warnFile := filepath.Join(warnDir, staleEndedSessionWarnFile)
	if info, statErr := os.Stat(warnFile); statErr == nil {
		if time.Since(info.ModTime()) < staleEndedSessionWarnInterval {
			return // rate-limited
		}
	}
	//nolint:errcheck,gosec // G104: Best-effort warning — fail-open if file ops fail
	os.MkdirAll(warnDir, 0o750)
	//nolint:errcheck,gosec // G104: Best-effort sentinel file write
	os.WriteFile(warnFile, []byte{}, 0o644)
	fmt.Fprintf(w,
		"\nentire: %d ended session(s) are accumulating and slowing down commits.\n"+
			"Run 'entire doctor' to condense them and restore commit performance.\n\n",
		count,
	)
}

// activeSessionInteractionThreshold is the maximum age of LastInteractionTime
// for an ACTIVE session to be considered genuinely active. 24h is generous
// because LastInteractionTime only updates at TurnStart, not per-tool-call.
const activeSessionInteractionThreshold = 24 * time.Hour

// isRecentInteraction returns true if lastInteraction is non-nil and within
// activeSessionInteractionThreshold of now.
func isRecentInteraction(lastInteraction *time.Time) bool {
	return lastInteraction != nil && time.Since(*lastInteraction) < activeSessionInteractionThreshold
}

func (h *postCommitActionHandler) HandleDiscardIfNoFiles(state *session.State) error {
	if len(state.FilesTouched) == 0 {
		logging.Debug(logging.WithComponent(h.ctx, "checkpoint"), "post-commit: skipping empty ended session (no files to condense)",
			slog.String("session_id", state.SessionID),
		)
	}
	h.s.updateBaseCommitIfChanged(h.ctx, state, h.newHead)
	return nil
}

func (h *postCommitActionHandler) HandleWarnStaleSession(_ *session.State) error {
	// Not produced by EventGitCommit; no-op for exhaustiveness.
	return nil
}

// During rebase/cherry-pick/revert operations, phase transitions are skipped entirely.
//

func (s *ManualCommitStrategy) PostCommit(ctx context.Context) error { //nolint:unparam // error return is part of the hook contract; callers check it
	logCtx := logging.WithComponent(ctx, "checkpoint")

	_, openRepoSpan := perf.Start(ctx, "open_repository_and_head")
	repo, err := OpenRepository(ctx)
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	// Get HEAD commit to check for trailer
	head, err := repo.Head()
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		openRepoSpan.RecordError(err)
		openRepoSpan.End()
		return nil
	}

	// Check if commit has checkpoint trailer (ParseCheckpoint validates format)
	checkpointID, found := trailers.ParseCheckpoint(commit.Message)
	openRepoSpan.End()

	if !found {
		// No trailer — user removed it or it was never added (mid-turn commit).
		// Still update BaseCommit for active sessions so future commits can match.
		s.postCommitUpdateBaseCommitOnly(ctx, head)
		return nil

// Package investigate contains the env-var contract between `entire
// investigate` (which spawns the agent process) and the lifecycle hook (which
// adopts the session), plus the persisted run state for resuming an
// investigation. These names are stable API; renaming any constant is a
// breaking change.
//
// Design rationale: each spawned agent inherits its own copy of the process
// environment, so multi-tenant correctness (multiple worktrees, multi-agent
// runs) holds by construction — one agent's env vars cannot bleed into
// another agent's session. The lifecycle UserPromptSubmit hook reads these
// env vars to tag the in-flight session as an investigate session (Kind =
// "agent_investigate") and records the run/round/turn coordinates.
package investigate

import (
	"strconv"

	"github.com/entireio/cli/cmd/entire/cli/provenance"
)

// Investigate env vars. Names live in cmd/entire/cli/provenance; aliased
// here for the package's call sites.
const (
	EnvSession     = provenance.InvestigateSession
	EnvAgent       = provenance.InvestigateAgent
	EnvRunID       = provenance.InvestigateRunID
	EnvRound       = provenance.InvestigateRound
	EnvTurn        = provenance.InvestigateTurn
	EnvTopic       = provenance.InvestigateTopic
	EnvPrompt      = provenance.InvestigatePrompt
	EnvFindingsDoc = provenance.InvestigateFindingsDoc
	EnvStateDoc    = provenance.InvestigateStateDoc
	EnvStartingSHA = provenance.InvestigateStartingSHA
)

// AppendOptions carries the data needed to populate the ENTIRE_INVESTIGATE_*
// env vars on a spawned agent process.
type AppendOptions struct {
	AgentName   string
	RunID       string
	Round       int
	Turn        int
	Topic       string
	Prompt      string
	FindingsDoc string
	StateDoc    string
	StartingSHA string
}

// AppendInvestigateEnv adds the ENTIRE_INVESTIGATE_* env vars to base,
// returning the new slice. Used by the loop driver when spawning each per-turn
// agent process to propagate the investigate-session contract.
//
// Any pre-existing ENTIRE_INVESTIGATE_* AND ENTIRE_REVIEW_* entries in base
// are stripped before the new values are appended. Stripping investigate
// entries handles nested invocations and stale inheritance from a parent
// shell — duplicate keys would otherwise have implementation-defined
// precedence. Stripping review entries prevents an outer `entire review`
// session from mis-tagging a child investigate session if invoked nested.
func AppendInvestigateEnv(base []string, opts AppendOptions) []string {
	out := make([]string, 0, len(base)+10)
	for _, kv := range base {
		if provenance.IsEntry(kv) {
			continue
		}
		out = append(out, kv)
	}
	return append(out,
		EnvSession+"=1",
		EnvAgent+"="+opts.AgentName,
		EnvRunID+"="+opts.RunID,
		EnvRound+"="+strconv.Itoa(opts.Round),
		EnvTurn+"="+strconv.Itoa(opts.Turn),
		EnvTopic+"="+opts.Topic,
		EnvPrompt+"="+opts.Prompt,
		EnvFindingsDoc+"="+opts.FindingsDoc,
		EnvStateDoc+"="+opts.StateDoc,
		EnvStartingSHA+"="+opts.StartingSHA,
	)
}

// IsInvestigateEnvEntry reports whether kv is a "KEY=VALUE" entry whose key
// is one of the ENTIRE_INVESTIGATE_* contract variables.
func IsInvestigateEnvEntry(kv string) bool {
	return provenance.IsInvestigateEntry(kv)
}

// Package provenance owns the env-var contract that lets the lifecycle hook
// recognize a spawned agent process as part of `entire review` or `entire
// investigate`. Both spawn families set their own ENTIRE_*_* vars on the
// child agent process; the UserPromptSubmit hook reads them to tag the
// in-flight session with the right Kind and provenance metadata.
//
// Single source of truth for the names — review, investigate, and
// agentlaunch (which strips both families before spawning a fix agent) all
// reference this package.
//
// These names are stable API; renaming any constant is a breaking change.
package provenance

import "strings"

const (
	ReviewSession     = "ENTIRE_REVIEW_SESSION"
	ReviewAgent       = "ENTIRE_REVIEW_AGENT"
	ReviewSkills      = "ENTIRE_REVIEW_SKILLS"
	ReviewPrompt      = "ENTIRE_REVIEW_PROMPT"
	ReviewStartingSHA = "ENTIRE_REVIEW_STARTING_SHA"

	InvestigateSession     = "ENTIRE_INVESTIGATE_SESSION"
	InvestigateAgent       = "ENTIRE_INVESTIGATE_AGENT"
	InvestigateRunID       = "ENTIRE_INVESTIGATE_RUN_ID"
	InvestigateRound       = "ENTIRE_INVESTIGATE_ROUND"
	InvestigateTurn        = "ENTIRE_INVESTIGATE_TURN"
	InvestigateTopic       = "ENTIRE_INVESTIGATE_TOPIC"
	InvestigatePrompt      = "ENTIRE_INVESTIGATE_PROMPT"
	InvestigateFindingsDoc = "ENTIRE_INVESTIGATE_FINDINGS_DOC"
	InvestigateStateDoc    = "ENTIRE_INVESTIGATE_STATE_DOC"
	InvestigateStartingSHA = "ENTIRE_INVESTIGATE_STARTING_SHA"
)

var reviewPrefixes = []string{
	ReviewSession + "=",
	ReviewAgent + "=",
	ReviewSkills + "=",
	ReviewPrompt + "=",
	ReviewStartingSHA + "=",
}

var investigatePrefixes = []string{
	InvestigateSession + "=",
	InvestigateAgent + "=",
	InvestigateRunID + "=",
	InvestigateRound + "=",
	InvestigateTurn + "=",
	InvestigateTopic + "=",
	InvestigatePrompt + "=",
	InvestigateFindingsDoc + "=",
	InvestigateStateDoc + "=",
	InvestigateStartingSHA + "=",
}

// IsReviewEntry reports whether kv is a "KEY=VALUE" entry whose key is one
// of the ENTIRE_REVIEW_* contract variables.
func IsReviewEntry(kv string) bool {
	return hasAnyPrefix(kv, reviewPrefixes)
}

// IsInvestigateEntry reports whether kv is a "KEY=VALUE" entry whose key is
// one of the ENTIRE_INVESTIGATE_* contract variables.
func IsInvestigateEntry(kv string) bool {
	return hasAnyPrefix(kv, investigatePrefixes)
}

// IsEntry reports whether kv is a "KEY=VALUE" entry from either family.
// agentlaunch uses this to strip provenance markers before spawning a fix
// session so the child is not tagged as review or investigate.
func IsEntry(kv string) bool {
	return IsReviewEntry(kv) || IsInvestigateEntry(kv)
}

func hasAnyPrefix(s string, prefixes []string) bool {
	for _, p := range prefixes {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

// Kind tags the session's purpose. Empty for normal agent sessions;
// set to KindAgentReview when the session was started by `entire review`.
Kind Kind `json:"kind,omitempty"`

// ReviewSkills is the snapshot of configured review skills at session start.
// Preserved so checkpoint metadata records which skills were run. May be
// empty when a review was attached post-hoc and skills were not declared;
// ReviewPrompt is the ground truth in that case.
ReviewSkills []string `json:"review_skills,omitempty"`

// ReviewPrompt is the actual text of the review request — the composed
// prompt sent to the agent (spawn path) or the session's first user
// prompt (attach path). Always populated when Kind is a review kind.
ReviewPrompt string `json:"review_prompt,omitempty"`

// InvestigateRunID is the 12-hex-char ID of the parent investigation
// run when Kind is an investigate kind. Multiple sessions across rounds
// share this ID so the loop driver can correlate them. Empty for
// non-investigate sessions.
InvestigateRunID string `json:"investigate_run_id,omitempty"`

// InvestigateRound is the round number (1-indexed) within the
// investigation run that produced this session. Only meaningful when
// Kind is an investigate kind.
InvestigateRound int `json:"investigate_round,omitempty"`

// InvestigateTurn is the overall turn index (1-indexed across rounds)
// within the investigation run that produced this session. Only
// meaningful when Kind is an investigate kind.
InvestigateTurn int `json:"investigate_turn,omitempty"`

// InvestigateTopic is the human-readable topic the investigation was
// asked to investigate. Snapshot at session start so checkpoint
// metadata records what the agent was investigating. Only meaningful
// when Kind is an investigate kind.
InvestigateTopic string `json:"investigate_topic,omitempty"`

// InvestigatePrompt is the actual text of the investigation request —
// the composed prompt sent to the agent for this turn. Always populated
// when Kind is an investigate kind.
InvestigatePrompt string `json:"investigate_prompt,omitempty"`

// TurnID is a unique identifier for the current agent turn.
// Lifecycle:
//   - Generated fresh in InitializeSession at each turn start
//   - Shared across all checkpoints within the same turn
//   - Used to correlate related checkpoints when a turn's work spans multiple commits
//   - Persists until the next InitializeSession call generates a new one
TurnID string `json:"turn_id,omitempty"`

// adoptInvestigateEnv tags the session as an investigation session when
// ENTIRE_INVESTIGATE_* env vars are present on the current process.
//
// Adoption ordering: adoptReviewEnv runs first; if both env families are
// somehow set on the same process, review wins. Production strips
// ENTIRE_REVIEW_* in AppendInvestigateEnv before spawning each per-turn
// agent process, so this conflict cannot happen for fresh investigate spawns
// — but tryAdoptEnv's short-circuit on state.Kind != "" makes the conflict
// harmless if it ever arises.
func adoptInvestigateEnv(ctx context.Context, state *session.State, expectedAgent string) {
	tryAdoptEnv(ctx, state, expectedAgent, envAdoptionSpec{
		kindLabel:      "investigate",
		envSession:     investigate.EnvSession,
		envAgent:       investigate.EnvAgent,
		envStartingSHA: investigate.EnvStartingSHA,
		apply: func(ctx context.Context, state *session.State, envAgent string) {
			round, roundErr := strconv.Atoi(os.Getenv(investigate.EnvRound))
			turn, turnErr := strconv.Atoi(os.Getenv(investigate.EnvTurn))
			if roundErr != nil || turnErr != nil {
				logging.Warn(ctx, "investigate env adoption failed: invalid round/turn",
					slog.String("round_err", errString(roundErr)),
					slog.String("turn_err", errString(turnErr)))
				return
			}
			runID := os.Getenv(investigate.EnvRunID)
			// Reject empty or malformed RunID — downstream condensation joins
			// session metadata by run ID, and tagging a session with no/invalid
			// ID would leak into checkpoint metadata as junk data.
			if !investigate.IsValidRunID(runID) {
				logging.Warn(ctx, "investigate env adoption skipped: invalid run id",
					slog.String("env_run_id", runID))
				return
			}
			state.Kind = session.KindAgentInvestigate
			state.InvestigateRunID = runID
			state.InvestigateRound = round
			state.InvestigateTurn = turn
			state.InvestigateTopic = os.Getenv(investigate.EnvTopic)
			state.InvestigatePrompt = os.Getenv(investigate.EnvPrompt)
			logging.Debug(ctx, "adopted investigate env",
				slog.String("agent", envAgent),
				slog.String("run_id", state.InvestigateRunID),
				slog.Int("round", round),
				slog.Int("turn", turn))
		},
	})
}

// errString returns "" for a nil error, err.Error() otherwise. Local helper
// to keep slog attrs tidy in the env-adoption functions above.

