3	import (
4		"slices"
5		"strings"
6		"testing"
7	)
8	
9	// TestEnvNamesAreStable pins each ENTIRE_INVESTIGATE_* constant by direct
10	// comparison so a rename surfaces on the specific constant that broke,
11	// rather than as one ambiguous map-iteration failure.
12	func TestEnvNamesAreStable(t *testing.T) {
13		t.Parallel()
14		if EnvSession != "ENTIRE_INVESTIGATE_SESSION" {
15			t.Errorf("EnvSession: got %q, want ENTIRE_INVESTIGATE_SESSION", EnvSession)
16		}
17		if EnvAgent != "ENTIRE_INVESTIGATE_AGENT" {
18			t.Errorf("EnvAgent: got %q, want ENTIRE_INVESTIGATE_AGENT", EnvAgent)
19		}
20		if EnvRunID != "ENTIRE_INVESTIGATE_RUN_ID" {
21			t.Errorf("EnvRunID: got %q, want ENTIRE_INVESTIGATE_RUN_ID", EnvRunID)
22		}
23		if EnvRound != "ENTIRE_INVESTIGATE_ROUND" {
24			t.Errorf("EnvRound: got %q, want ENTIRE_INVESTIGATE_ROUND", EnvRound)
25		}
26		if EnvTurn != "ENTIRE_INVESTIGATE_TURN" {
27			t.Errorf("EnvTurn: got %q, want ENTIRE_INVESTIGATE_TURN", EnvTurn)
28		}
29		if EnvTopic != "ENTIRE_INVESTIGATE_TOPIC" {
30			t.Errorf("EnvTopic: got %q, want ENTIRE_INVESTIGATE_TOPIC", EnvTopic)
31		}
32		if EnvPrompt != "ENTIRE_INVESTIGATE_PROMPT" {
33			t.Errorf("EnvPrompt: got %q, want ENTIRE_INVESTIGATE_PROMPT", EnvPrompt)
34		}
35		if EnvFindingsDoc != "ENTIRE_INVESTIGATE_FINDINGS_DOC" {
36			t.Errorf("EnvFindingsDoc: got %q, want ENTIRE_INVESTIGATE_FINDINGS_DOC", EnvFindingsDoc)
37		}
38		if EnvStateDoc != "ENTIRE_INVESTIGATE_STATE_DOC" {
39			t.Errorf("EnvStateDoc: got %q, want ENTIRE_INVESTIGATE_STATE_DOC", EnvStateDoc)
40		}
41		if EnvStartingSHA != "ENTIRE_INVESTIGATE_STARTING_SHA" {
42			t.Errorf("EnvStartingSHA: got %q, want ENTIRE_INVESTIGATE_STARTING_SHA", EnvStartingSHA)
43		}
44	}
45	
46	// TestIsInvestigateEnvEntry pins the prefix-matching helper used to strip
47	// stale ENTIRE_INVESTIGATE_* entries before AppendInvestigateEnv writes new
48	// ones.
49	func TestIsInvestigateEnvEntry(t *testing.T) {
50		t.Parallel()
51		tests := []struct {
52			kv   string
53			want bool
54		}{
55			{EnvSession + "=1", true},
56			{EnvAgent + "=claude-code", true},
57			{EnvRunID + "=abcdef012345", true},
58			{EnvRound + "=2", true},
59			{EnvTurn + "=5", true},
60			{EnvTopic + "=topic", true},
61			{EnvPrompt + "=prompt", true},
62			{EnvFindingsDoc + "=/tmp/x", true},
63			{EnvStateDoc + "=/tmp/state.json", true},
64			{EnvStartingSHA + "=deadbeef", true},
65			{"PATH=/usr/bin", false},
66			{"HOME=/home/u", false},
67			{"ENTIRE_REVIEW_SESSION=1", false},    // review entries are not investigate entries
68			{"ENTIRE_INVESTIGATE_OTHER=1", false}, // unknown investigate-style key
69			{"NOT_ENTIRE_INVESTIGATE_SESSION", false},
70		}
71		for _, tc := range tests {
72			if got := IsInvestigateEnvEntry(tc.kv); got != tc.want {
73				t.Errorf("IsInvestigateEnvEntry(%q) = %v, want %v", tc.kv, got, tc.want)
74			}
75		}
76	}
77	
78	// TestAppendInvestigateEnv_StripsStaleInvestigateAndReview pins the contract
79	// that AppendInvestigateEnv removes both ENTIRE_INVESTIGATE_* and
80	// ENTIRE_REVIEW_* entries before appending fresh values. The review-strip
81	// is the risk-mitigation guard for a child investigate process inheriting
82	// review env from a parent shell.
83	func TestAppendInvestigateEnv_StripsStaleInvestigateAndReview(t *testing.T) {
84		t.Parallel()
85		base := []string{
86			"PATH=/usr/bin",
87			"HOME=/home/u",
88			// stale investigate vars from a previous run
89			EnvSession + "=stale",
90			EnvAgent + "=stale-agent",
91			EnvRunID + "=staleeeeeeee",
92			EnvRound + "=99",
93			EnvTurn + "=99",
94			EnvTopic + "=stale topic",
95			EnvPrompt + "=stale prompt",
96			EnvFindingsDoc + "=/tmp/stale-findings.md",
97			EnvStateDoc + "=/tmp/stale-state.json",
98			EnvStartingSHA + "=stalehash",
99			// stale review vars from an outer review process
100			"ENTIRE_REVIEW_SESSION=1",
101			"ENTIRE_REVIEW_AGENT=stale-review-agent",
102			"ENTIRE_REVIEW_SKILLS=[\"/stale\"]",
103			"ENTIRE_REVIEW_PROMPT=stale review prompt",
104			"ENTIRE_REVIEW_STARTING_SHA=stalehash",
105		}
106		got := AppendInvestigateEnv(base, AppendOptions{
107			AgentName:   "claude-code",
108			RunID:       "abcdef012345",
109			Round:       1,
110			Turn:        2,
111			Topic:       "fresh topic",
112			Prompt:      "fresh prompt",
113			FindingsDoc: "/tmp/fresh-findings.md",
114			StateDoc:    "/tmp/fresh-state.json",
115			StartingSHA: "freshhash",
116		})
117	
118		want := map[string]string{
119			EnvSession:     "1",
120			EnvAgent:       "claude-code",
121			EnvRunID:       "abcdef012345",
122			EnvRound:       "1",
123			EnvTurn:        "2",
124			EnvTopic:       "fresh topic",
125			EnvPrompt:      "fresh prompt",
126			EnvFindingsDoc: "/tmp/fresh-findings.md",
127			EnvStateDoc:    "/tmp/fresh-state.json",
128			EnvStartingSHA: "freshhash",
129		}
130		counts := make(map[string]int)
131		values := make(map[string]string)
132		for _, kv := range got {
133			for key := range want {
134				prefix := key + "="
135				if strings.HasPrefix(kv, prefix) {
136					counts[key]++
137					values[key] = kv[len(prefix):]
138				}
139			}
140		}
141		for key, wantVal := range want {
