14	)
15	
16	// CommittedReader provides read access to committed checkpoint data.
17	// Both GitStore (v1) and V2GitStore (v2) implement this interface.
18	type CommittedReader interface {
19		ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
20		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
21	}
22	
23	// CommittedListReader provides read and list access to committed checkpoint data.
24	// GitStore, V2GitStore, and DualCheckpointReader implement this interface.
25	type CommittedListReader interface {
26		CommittedReader
27		ListCommitted(ctx context.Context) ([]CommittedInfo, error)
28		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error)
29	}
30	
31	type CommittedReadMode int
32	
33	const (
34		CommittedReadV1 CommittedReadMode = iota
35		CommittedReadDual
36		CommittedReadV2
37	)
38	
39	func CommittedReadModeForOptions(checkpointsV2Enabled bool, checkpointsVersion int) CommittedReadMode {
40		if checkpointsVersion == 2 {
41			return CommittedReadV2
42		}
43		if checkpointsV2Enabled {
44			return CommittedReadDual
45		}
46		return CommittedReadV1
47	}
48	
49	func NewCommittedReader(v1Store *GitStore, v2Store *V2GitStore, mode CommittedReadMode) (CommittedListReader, error) {
50		switch mode {
51		case CommittedReadV2:
52			if v2Store == nil {
53				return nil, errors.New("v2 committed checkpoint reader unavailable")
54			}
55			return v2Store, nil
56		case CommittedReadDual:
57			switch {
58			case v2Store == nil && v1Store == nil:
59				return nil, errors.New("committed checkpoint reader unavailable")
60			case v2Store == nil:
61				return v1Store, nil
62			case v1Store == nil:
63				return v2Store, nil
64			default:
65				return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
66			}
67		case CommittedReadV1:
68			if v1Store == nil {
69				return nil, errors.New("v1 committed checkpoint reader unavailable")
70			}
71			return v1Store, nil
72		default:
73			return nil, fmt.Errorf("unknown committed checkpoint read mode: %d", mode)
74		}
75	}
76	
77	type DualCheckpointReader struct {
78		v2 *V2GitStore
79		v1 *GitStore
80	}
81	
82	func (r *DualCheckpointReader) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
83		summary, err := r.v2.ReadCommitted(ctx, checkpointID)
84		if err == nil && summary != nil {
85			return summary, nil
86		}
87		if ctxErr := ctx.Err(); ctxErr != nil {
88			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
89		}
90		if err != nil {
91			logV2Fallback(ctx, "v2 ReadCommitted failed, falling back to v1", checkpointID, err)
92		}
93		return r.v1.ReadCommitted(ctx, checkpointID)
94	}
95	
96	func (r *DualCheckpointReader) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
97		content, err := r.v2.ReadSessionContent(ctx, checkpointID, sessionIndex)
98		if err == nil {
99			return content, nil
100		}
101		if ctxErr := ctx.Err(); ctxErr != nil {
102			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
103		}
104		if errors.Is(err, ErrCheckpointNotFound) {
105			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
106			if existsErr != nil {
107				return nil, existsErr
108			}
109			if v2CheckpointExists {
110				return r.readSingleV1SessionContent(ctx, checkpointID, sessionIndex, err)
111			}
112			return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
113		}
114		sessionID, sessionIDErr := r.v2SessionID(ctx, checkpointID, sessionIndex)
115		if sessionIDErr != nil {
116			if ctxErr := ctx.Err(); ctxErr != nil {
117				return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
118			}
119			originalErr := fallbackReadError(err, "read v2 session metadata for v1 fallback", sessionIDErr)
120			return r.readSingleV1SessionContent(ctx, checkpointID, sessionIndex, originalErr)
121		}
122		return r.readV1SessionContentByID(ctx, checkpointID, sessionID, err)
123	}
124	
125	func (r *DualCheckpointReader) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error) {
126		metadata, err := r.v2.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
127		if err == nil {
128			return metadata, nil
129		}
130		if ctxErr := ctx.Err(); ctxErr != nil {
131			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
132		}
133		if errors.Is(err, ErrCheckpointNotFound) {
134			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
135			if existsErr != nil {
136				return nil, existsErr
137			}
138			if v2CheckpointExists {
139				return r.readSingleV1SessionMetadata(ctx, checkpointID, sessionIndex, err)
140			}
141			return r.readV1SessionMetadataByIndex(ctx, checkpointID, sessionIndex, err)
142		}
143		return r.readSingleV1SessionMetadata(ctx, checkpointID, sessionIndex, err)
144	}
145	
146	// ReadSessionMetadataAndPrompts is intentionally v2-only because callers pair
147	// this metadata with the v2 compact transcript. Returning v1 raw content here
148	// would bypass the checkpoint transcript offset handling in ReadSessionContent.
149	func (r *DualCheckpointReader) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
150		return r.v2.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
151	}
152	
153	func (r *DualCheckpointReader) ReadSessionCompactTranscript(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
154		return r.v2.ReadSessionCompactTranscript(ctx, checkpointID, sessionIndex)
155	}
156	
157	func (r *DualCheckpointReader) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
158		v2Committed, v2Err := r.v2.ListCommitted(ctx)
159		v1Committed, v1Err := r.v1.ListCommitted(ctx)
160	
161		if v2Err != nil {
162			logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
163				slog.String("error", v2Err.Error()),
164			)
165			if v1Err != nil {
166				return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
167			}
168			return v1Committed, nil
169		}
170	
171		if v1Err != nil {
172			logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
173				slog.String("error", v1Err.Error()),
174			)
175			return v2Committed, nil
176		}
177	
178		seen := make(map[id.CheckpointID]struct{}, len(v2Committed))
179		for _, c := range v2Committed {
180			seen[c.CheckpointID] = struct{}{}
181		}
182		committed := make([]CommittedInfo, 0, len(v2Committed)+len(v1Committed))
183		committed = append(committed, v2Committed...)
184		for _, c := range v1Committed {
185			if _, ok := seen[c.CheckpointID]; !ok {
186				committed = append(committed, c)
187			}
188		}
189		return committed, nil
190	}
191	
192	func (r *DualCheckpointReader) v2CheckpointExists(ctx context.Context, checkpointID id.CheckpointID) (bool, error) {
193		if err := ctx.Err(); err != nil {
194			return false, err //nolint:wrapcheck // Propagating context cancellation
195		}
196		checkpointExists := false
197		_, rootTreeHash, err := r.v2.GetRefState(plumbing.ReferenceName(paths.V2MainRefName))
198		if err == nil {
199			rootTree, err := r.v2.repo.TreeObject(rootTreeHash)
200			if err == nil {
201				_, err = rootTree.Tree(checkpointID.Path())
202				checkpointExists = err == nil
203			}
204		}
205		return checkpointExists, nil
206	}
207	
208	func (r *DualCheckpointReader) v2SessionID(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
209		metadata, err := r.v2.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
210		if err != nil {
211			return "", err
212		}
213		if metadata == nil || metadata.SessionID == "" {
214			return "", ErrNoTranscript
215		}

